namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string CourseCode { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public string DepartmentId { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

namespace UniversityCourseCatalog.Models;

public class Department
{
    public string Id { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9\-]+$", ErrorMessage = "Invalid Student ID format.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    public int? CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public interface ICatalogService
{
    IReadOnlyList<Department> GetDepartments();
    Department? GetDepartment(string id);
    IReadOnlyList<Course> GetCourses(string? departmentId = null, string? search = null);
    Course? GetCourse(int id);
    IReadOnlyList<Course> GetFeaturedCourses();
    bool SubmitEnrollment(EnrollmentRequest request);
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService : ICatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Id = "cs", Name = "Computer Science", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = "math", Name = "Mathematics", Description = "Pure and applied mathematics, statistics, and data analysis." },
        new() { Id = "eng", Name = "English", Description = "Literature, writing, and language studies." },
        new() { Id = "phys", Name = "Physics", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = "hist", Name = "History", Description = "Exploration of past events, societies, and civilizations." },
    ];

    private static readonly List<Course> Courses =
    [
        new() { Id = 1, CourseCode = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on pedagogy in computing education.", DepartmentId = "cs", IsFeatured = true },
        new() { Id = 2, CourseCode = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques (divide-and-conquer, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Okafor", InstructorBio = "Dr. Okafor specializes in algorithm optimization and has contributed to open-source projects in high-performance computing.", DepartmentId = "cs", IsFeatured = true },
        new() { Id = 3, CourseCode = "CS 310", Title = "Database Systems", Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL databases.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Prof. Maria Lopez", InstructorBio = "Prof. Lopez spent a decade in industry building large-scale distributed databases before joining academia.", DepartmentId = "cs" },
        new() { Id = 4, CourseCode = "MATH 151", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator known for making calculus accessible to all students.", DepartmentId = "math", IsFeatured = true },
        new() { Id = 5, CourseCode = "MATH 250", Title = "Linear Algebra", Description = "Vector spaces, matrices, determinants, eigenvalues, and linear transformations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Emily Zhao", InstructorBio = "Dr. Zhao researches applications of linear algebra in machine learning and data science.", DepartmentId = "math" },
        new() { Id = 6, CourseCode = "ENG 110", Title = "College Writing", Description = "Develop critical thinking and academic writing skills through essay composition and peer review.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Prof. David Nguyen", InstructorBio = "Prof. Nguyen is a published author and writing workshop facilitator with expertise in rhetoric and composition.", DepartmentId = "eng" },
        new() { Id = 7, CourseCode = "ENG 230", Title = "American Literature", Description = "Survey of American literature from the colonial period to the present, exploring themes of identity, freedom, and social change.", Credits = 3, Schedule = "Mon/Wed 11:00 AM–12:15 PM", InstructorName = "Dr. Angela Morrison", InstructorBio = "Dr. Morrison's research focuses on 20th-century African American literature and cultural criticism.", DepartmentId = "eng", IsFeatured = true },
        new() { Id = 8, CourseCode = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions.", Credits = 4, Schedule = "Mon/Wed/Fri 11:00–11:50 AM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Alan Petrov", InstructorBio = "Dr. Petrov is an experimental physicist who brings real-world demonstrations into every lecture.", DepartmentId = "phys" },
        new() { Id = 9, CourseCode = "PHYS 220", Title = "Electromagnetism", Description = "Electric fields, magnetic fields, Maxwell's equations, and electromagnetic waves.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM + Fri Lab 1:00–3:50 PM", InstructorName = "Dr. Lisa Park", InstructorBio = "Dr. Park's research in photonics has been published in leading journals. She is passionate about making physics intuitive.", DepartmentId = "phys" },
        new() { Id = 10, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations from antiquity through the medieval period, including Mesopotamia, Greece, Rome, China, and the Islamic world.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is a medieval historian who has conducted archaeological fieldwork across Europe and the Middle East.", DepartmentId = "hist", IsFeatured = true },
    ];

    public IReadOnlyList<Department> GetDepartments() => Departments;

    public Department? GetDepartment(string id) =>
        Departments.FirstOrDefault(d => d.Id == id);

    public IReadOnlyList<Course> GetCourses(string? departmentId = null, string? search = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(departmentId))
        {
            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
        }

        if (!string.IsNullOrWhiteSpace(search))
        {
            var term = search.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) =>
        Courses.FirstOrDefault(c => c.Id == id);

    public IReadOnlyList<Course> GetFeaturedCourses() =>
        Courses.Where(c => c.IsFeatured).ToList();

    public bool SubmitEnrollment(EnrollmentRequest request)
    {
        // In a real application this would persist to a database.
        return request.CourseId.HasValue && GetCourse(request.CourseId.Value) is not null;
    }
}

