+        new() { Id = 10, CourseCode = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations from antiquity through the medieval period, including Mesopotamia, Greece, Rome, China, and the Islamic world.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", InstructorName = "Dr. Thomas Grant", InstructorBio = "Dr. Grant is a medieval historian who has conducted archaeological fieldwork across Europe and the Middle East.", DepartmentId = "hist", IsFeatured = true },
+    ];
+
+    public IReadOnlyList<Department> GetDepartments() => Departments;
+
+    public Department? GetDepartment(string id) =>
+        Departments.FirstOrDefault(d => d.Id == id);
+
+    public IReadOnlyList<Course> GetCourses(string? departmentId = null, string? search = null)
+    {
+        var query = Courses.AsEnumerable();
+
+        if (!string.IsNullOrWhiteSpace(departmentId))
+        {
+            query = query.Where(c => c.DepartmentId.Equals(departmentId, StringComparison.OrdinalIgnoreCase));
+        }
+
+        if (!string.IsNullOrWhiteSpace(search))
+        {
+            var term = search.Trim();
+            query = query.Where(c =>
+                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
+                c.CourseCode.Contains(term, StringComparison.OrdinalIgnoreCase) ||
+                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
+        }
+
+        return query.ToList();
+    }
+
+    public Course? GetCourse(int id) =>
+        Courses.FirstOrDefault(c => c.Id == id);
+
+    public IReadOnlyList<Course> GetFeaturedCourses() =>
+        Courses.Where(c => c.IsFeatured).ToList();
+
+    public bool SubmitEnrollment(EnrollmentRequest request)
+    {
+        // In a real application this would persist to a database.
+        return request.CourseId.HasValue && GetCourse(request.CourseId.Value) is not null;
+    }
