.navbar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    max-width: 1200px;
    margin: 0 auto;
    height: 60px;
}

.brand {
    color: #fff;
    font-size: 1.25rem;
    font-weight: 700;
    text-decoration: none;
}

.nav-links {
    list-style: none;
    display: flex;
    gap: 1.5rem;
    margin: 0;
    padding: 0;
}

.nav-links a {
    color: #d0e0f0;
    text-decoration: none;
    font-weight: 500;
}

.nav-links a:hover {
    color: #fff;
    text-decoration: underline;
}

.content-area {
    flex: 1;
    max-width: 1200px;
    margin: 0 auto;
    padding: 2rem 1.5rem;
    width: 100%;
}

.site-footer {
    background-color: #f0f0f0;
    text-align: center;
    padding: 1rem;
    font-size: 0.875rem;
    color: #666;
}

.hero {
    text-align: center;
    padding: 2rem 1rem 3rem;
}

.hero h1 {
    font-size: 2rem;
    color: #1b3a5c;
}

.hero p {
    font-size: 1.1rem;
    color: #555;
}

.departments-section,
.featured-section {
    margin-bottom: 3rem;
}

.departments-section h2,
.featured-section h2 {
    color: #1b3a5c;
    border-bottom: 2px solid #e0e0e0;
    padding-bottom: 0.5rem;
    margin-bottom: 1rem;
}

.department-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1rem;
}

.department-card {
    display: block;
    padding: 1.25rem;
    border: 1px solid #ddd;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
}

.department-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

.department-card h3 {
    margin: 0 0 0.5rem;
    color: #1b3a5c;
}

.department-card p {
    margin: 0;
    font-size: 0.9rem;
    color: #666;
}

.course-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
    gap: 1rem;
}

.course-card {
    display: block;
    padding: 1.25rem;
    border: 1px solid #ddd;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
}

.course-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

.course-code {
    font-size: 0.8rem;
    font-weight: 600;
    color: #888;
    text-transform: uppercase;
}

.course-card h3 {
    margin: 0.25rem 0 0.5rem;
    color: #1b3a5c;
}

.course-card p {
    margin: 0;
    font-size: 0.9rem;
    color: #555;
}

