<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p class="page-description">Fill out the form below to request enrollment in a course.</p>

@if (submitted)
{
    <div class="success-message">
        <h2>✓ Request Submitted</h2>
        <p>Your enrollment request has been submitted successfully. You will receive a confirmation via your university email.</p>
        <a href="/courses">Browse more courses</a>
    </div>
}
else
{
    <EditForm method="post" Model="Model" OnValidSubmit="HandleSubmit" FormName="enrollment" Enhance>
        <DataAnnotationsValidator />
        <AntiforgeryToken />

        <div class="form-group">
            <label for="studentName">Full Name</label>
            <InputText id="studentName" @bind-Value="Model.StudentName" class="form-control" />
            <ValidationMessage For="() => Model.StudentName" />
        </div>

        <div class="form-group">
            <label for="studentId">Student ID</label>
            <InputText id="studentId" @bind-Value="Model.StudentId" class="form-control" placeholder="e.g., STU-12345" />
            <ValidationMessage For="() => Model.StudentId" />
        </div>

        <div class="form-group">
            <label for="courseId">Course</label>
            <InputSelect id="courseId" @bind-Value="Model.CourseId" class="form-control">
                <option value="">-- Select a course --</option>
                @foreach (var course in Catalog.GetCourses())
                {
                    <option value="@course.Id">@course.CourseCode — @course.Title</option>
                }
            </InputSelect>
            <ValidationMessage For="() => Model.CourseId" />
        </div>

        <button type="submit" class="btn-submit">Submit Enrollment Request</button>
    </EditForm>
}

@code {
    [SupplyParameterFromForm]
    private EnrollmentRequest Model { get; set; } = new();

    private bool submitted;

    private void HandleSubmit()
    {
        if (Catalog.SubmitEnrollment(Model))
        {
            submitted = true;
        }
    }
}
", "path": "/tmp/sv-8a0a1bc97ee8423b99b52dc9d3dfc293/UniversityCourseCatalog/Components/Pages/Enroll.razor"}

{"file_text": ".page-description {
    color: #555;
    margin-bottom: 1.5rem;
}

.form-group {
    margin-bottom: 1.25rem;
}

.form-group label {
    display: block;
    font-weight: 600;
    margin-bottom: 0.35rem;
    color: #333;
}

.form-control {
    width: 100%;
    max-width: 500px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.form-control:focus {
    outline: none;
    border-color: #1b3a5c;
    box-shadow: 0 0 0 2px rgba(27, 58, 92, 0.15);
}

.validation-message {
    color: #c0392b;
    font-size: 0.85rem;
    margin-top: 0.25rem;
}

.btn-submit {
    padding: 0.65rem 1.5rem;
    background-color: #1b3a5c;
    color: #fff;
    border: none;
    border-radius: 6px;
    font-size: 1rem;
    font-weight: 600;
    cursor: pointer;
    margin-top: 0.5rem;
}

.btn-submit:hover {
    background-color: #264d73;
}

.success-message {
    background: #eafaf1;
    border: 1px solid #27ae60;
    border-radius: 8px;
    padding: 1.5rem;
    max-width: 500px;
}

.success-message h2 {
    color: #27ae60;
    margin: 0 0 0.5rem;
}

.success-message p {
    color: #333;
    margin-bottom: 1rem;
}

.success-message a {
    color: #1b3a5c;
    font-weight: 600;
}
