toolArgs.file_text:
@page "/courses"
@inject ICatalogService Catalog

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="/courses" class="filter-bar">
    <input type="text" name="search" value="@Search" placeholder="Search by title, code, or instructor..." class="search-input" />
    <select name="department" class="dept-select">
        <option value="">All Departments</option>
        @foreach (var dept in Catalog.GetDepartments())
        {
            <option value="@dept.Id" selected="@(dept.Id == Department)">@dept.Name</option>
        }
    </select>
    <button type="submit" class="btn-search">Search</button>
</form>

@{
    var courses = Catalog.GetCourses(Department, Search);
}

@if (courses.Count == 0)
{
    <p class="no-results">No courses found matching your criteria.</p>
}
else
{
    <p class="result-count">Showing @courses.Count course(s)</p>
    <div class="course-list">
        @foreach (var course in courses)
        {
            <a class="course-item" href="@($"/courses/{course.Id}")">
                <div class="course-item-header">
                    <span class="course-code">@course.CourseCode</span>
                    <span class="course-credits">@course.Credits cr</span>
                </div>
                <h3>@course.Title</h3>
                <p class="course-meta">@course.InstructorName &middot; @course.Schedule</p>
            </a>
        }
    </div>
}

@code {
    [SupplyParameterFromQuery]
    public string? Search { get; set; }

    [SupplyParameterFromQuery]
    public string? Department { get; set; }
}

.filter-bar {
    display: flex;
    gap: 0.75rem;
    flex-wrap: wrap;
    margin-bottom: 1.5rem;
    padding: 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.search-input {
    flex: 1;
    min-width: 200px;
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.dept-select {
    padding: 0.5rem 0.75rem;
    border: 1px solid #ccc;
    border-radius: 4px;
    font-size: 0.95rem;
}

.btn-search {
    padding: 0.5rem 1.25rem;
    background-color: #1b3a5c;
    color: #fff;
    border: none;
    border-radius: 4px;
    cursor: pointer;
    font-size: 0.95rem;
}

.btn-search:hover {
    background-color: #264d73;
}

.no-results {
    color: #888;
    font-style: italic;
    margin-top: 1rem;
}

.result-count {
    color: #666;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.course-list {
    display: flex;
    flex-direction: column;
    gap: 0.75rem;
}

.course-item {
    display: block;
    padding: 1rem 1.25rem;
    border: 1px solid #ddd;
    border-radius: 8px;
    text-decoration: none;
    color: inherit;
    transition: box-shadow 0.2s;
}

.course-item:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.1);
}

.course-item-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.25rem;
}

.course-code {
    font-size: 0.8rem;
    font-weight: 600;
    color: #888;
    text-transform: uppercase;
}

.course-credits {
    font-size: 0.8rem;
    background: #e8f0fe;
    color: #1b3a5c;
    padding: 0.15rem 0.5rem;
    border-radius: 4px;
    font-weight: 600;
}

.course-item h3 {
    margin: 0 0 0.25rem;
    color: #1b3a5c;
}

.course-meta {
    margin: 0;
    font-size: 0.875rem;
    color: #666;
}

